import React from "react";
import { useLocation } from "react-router-dom";
import { listings } from "../list";
import FeaturedListings from "./Resuable/FeatureListtings";

export default function SearchResultsPage() {
  const location = useLocation();
  const query = new URLSearchParams(location.search).get("query") || "";
  const category = new URLSearchParams(location.search).get("category") || "All";

  // Filter the listings based on query and category
  const filteredListings = Object.entries(listings)
    .flatMap(([key, items]) => (category === "All" || key === category ? items : []))
    .filter((listing) =>
      query ? listing.title.toLowerCase().includes(query.toLowerCase()) : true
    );

  return (
    <div className="container mx-auto px-4 py-6">
      <h1 className="text-3xl font-semibold text-gray-800 mb-6">
        Search Results for "{query}" in "{category}"
      </h1>
      {filteredListings.length > 0 ? (
        <FeaturedListings listings={filteredListings} />
      ) : (
        <p className="text-gray-600">No results found.</p>
      )}
    </div>
  );
}
